(()=>{const el=id=>document.getElementById(id);let racePace=315,goalPace=315,hasHistory=false,manual=false,target=390,active=false,paused=false,watch=null,timer=null,tracker=null,epoch=0,pausedAt=0,pausedMs=0,wake=null,audio=null,lastFixAt=0,demo=false,runDistance=5,finished=false;const time=s=>{s=Math.max(0,Math.round(s));return s>=3600?Math.floor(s/3600)+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0'):Math.floor(s/60)+':'+String(s%60).padStart(2,'0')},parse=s=>{if(!s.trim())return NaN;let a=s.trim().split(':').map(Number);if(a.some(x=>!Number.isFinite(x)||x<0)||a.length>3)return NaN;return a.length===1?a[0]*60:a.reduce((s,n)=>s*60+n,0)},km=()=>{let v=+el('run-distance').value;return Number.isFinite(v)&&v>0?v:5};
function recommendation(){const energy=el('run-energy').value,gap=el('run-gap').value,type=el('run-type').value,protect=energy==='tired'||energy==='low'||gap!=='recent',effective=protect?'easy':type;return StrideRun.todayTarget(effective==='goal'?goalPace:racePace,effective,energy,gap)}
function advice(){const recommended=recommendation(),gap=el('run-gap').value,energy=el('run-energy').value;el('run-advice').textContent=(hasHistory?'Suggested today: '+time(recommended)+' /km. ':'Choose your pace, or add race history below for a personal starting point. ')+(gap==='long'?'After a longer break, start short and easy; run/walk is fine. ':energy==='tired'||energy==='low'?'Keep it easy today and shorten the run if needed. ':energy==='energetic'?'Enjoy the energy without turning an easy day into a race. ':'Let conversational effort lead on easy days. ')+(manual?'Your custom target is kept.':'Suggestions are simple planning adjustments, not a readiness assessment.')}
function apply(){manual=false;target=recommendation();el('run-pace').value=time(target);el('run-time').value=time(target*km());advice()}
for(const id of ['run-energy','run-gap','run-type'])el(id).onchange=()=>{if(!manual)apply();else advice()};el('apply-run-suggestion').onclick=apply;el('run-pace').oninput=()=>{let v=parse(el('run-pace').value);manual=true;if(v>0){target=v;el('run-time').value=time(target*km())}advice()};el('run-time').oninput=()=>{let v=parse(el('run-time').value);manual=true;if(v>0){target=v/km();el('run-pace').value=time(target)}advice()};el('run-distance').oninput=()=>{el('run-time').value=time(target*km());advice()};window.addEventListener('stride-plan',e=>{racePace=e.detail.m.base/e.detail.p.goal;goalPace=e.detail.m.goalTarget/e.detail.p.goal;hasHistory=true;if(!active&&!manual)apply()});el('open-run').onclick=()=>el('today-run').scrollIntoView({behavior:'smooth'});
async function prepareAudio(){try{const AC=window.AudioContext||window.webkitAudioContext;if(AC){audio=audio||new AC();await audio.resume()}}catch{}}
function tone(status){if(!el('run-sound').checked||!audio||audio.state!=='running')return;const notes=status==='on'?[659,831,988]:status==='fast'?[880,660]:[440,440];notes.forEach((f,i)=>{let o=audio.createOscillator(),g=audio.createGain(),at=audio.currentTime+i*.18;o.frequency.value=f;o.type='sine';g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(.16,at+.015);g.gain.exponentialRampToValueAtTime(.001,at+.14);o.connect(g);g.connect(audio.destination);o.start(at);o.stop(at+.16)})}
el('test-sound').onclick=async()=>{await prepareAudio();tone('on');setTimeout(()=>tone('fast'),1000);setTimeout(()=>tone('slow'),2000);el('run-advice').textContent='Listen: rising notes = on pace; falling notes = faster; two low notes = slower. Alerts compare each completed kilometre, within ±10 sec/km.'};
async function keepAwake(){try{wake=await navigator.wakeLock?.request('screen')}catch{}}
function elapsed(){return epoch?((paused?pausedAt:Date.now())-epoch-pausedMs)/1000:0}
function display(){el('live-distance').textContent=((tracker?.distance||0)/1000).toFixed(2);el('live-time').textContent=time(elapsed());if(active&&!paused&&epoch&&Date.now()-lastFixAt>30000){el('run-status').textContent='GPS signal interrupted · next split may be incomplete';el('run-status').dataset.state='gap'}}
function lapLine(l){const labels={on:'On target',fast:'Faster · ease back if this is an easy run',slow:'Slower · stay comfortable',gap:'GPS gap · split unavailable'};el('live-pace').textContent=l.reliable?time(l.pace):'—';el('run-status').textContent='KM '+l.km+' · '+labels[l.status];el('run-status').dataset.state=l.status;let row=document.createElement('div');row.className='split-row';row.textContent='KM '+l.km+' · '+(l.reliable?time(l.pace)+' /km · ':'')+labels[l.status];el('run-splits').prepend(row);if(l.reliable){tone(l.status);navigator.vibrate?.(l.status==='on'?[80,60,80]:[200])}}
function showLive(isDemo=false){document.body.classList.add("running-mode");demo=isDemo;finished=false;el('run-setup').hidden=true;el('run-live').hidden=false;el('new-run').hidden=true;el('run-splits').replaceChildren();el('live-pace').textContent='—';el('live-distance').textContent='0.00';el('live-time').textContent='0:00';el('live-target').textContent='TARGET '+time(target)+' /km · '+runDistance+' KM'+(isDemo?' · DEMO':'');el('pause-run').hidden=isDemo;el('finish-run').hidden=isDemo;el('pause-run').textContent='Pause';el('run-status').dataset.state='';}
el('start-run').onclick=async()=>{if(active)return;runDistance=km();await prepareAudio();showLive();el('run-status').textContent='Finding GPS · allow location to begin';if(!navigator.geolocation){el('run-status').textContent='GPS is unavailable here. Try the demo or use a phone browser.';el('new-run').hidden=false;return}active=true;paused=false;epoch=0;pausedMs=0;tracker=StrideRun.createTracker(target);watch=navigator.geolocation.watchPosition(position=>{if(!active||paused)return;const c=position.coords;if(c.accuracy>35){tracker.resetAnchor();el('run-status').textContent='Waiting for a clearer GPS signal';return}if(!epoch){epoch=Date.now();pausedMs=0;lastFixAt=Date.now();keepAwake()}lastFixAt=Date.now();const result=tracker.update({lat:c.latitude,lon:c.longitude,accuracy:c.accuracy,elapsed:elapsed()});if(!result.laps.length&&result.status==='ready'&&tracker.distance<1000)el('run-status').textContent='Running · next alert at '+(Math.floor(tracker.distance/1000)+1)+' km';if(result.status==='jump')el('run-status').textContent='GPS jump ignored · waiting for a stable fix';result.laps.forEach(lapLine);display();if(tracker.distance>=runDistance*1000)finish(true)},()=>{el('run-status').textContent='GPS is not available right now. Allow location in your browser to use live tracking, or try the demo.';stop();el('new-run').hidden=false},{enableHighAccuracy:true,maximumAge:0,timeout:20000});timer=setInterval(display,1000)};
el('pause-run').onclick=async()=>{if(!active)return;if(!paused){paused=true;pausedAt=Date.now();tracker.resetAnchor();el('pause-run').textContent='Resume';el('run-status').textContent='Paused · timer and distance stopped';wake?.release();wake=null}else{pausedMs+=Date.now()-pausedAt;paused=false;lastFixAt=Date.now();tracker.resetAnchor();el('pause-run').textContent='Pause';el('run-status').textContent='Resumed · finding a stable GPS fix';await prepareAudio();keepAwake()}display()};
function stop(){active=false;if(watch!==null){navigator.geolocation?.clearWatch(watch);watch=null}clearInterval(timer);timer=null;wake?.release();wake=null;el('pause-run').hidden=true;el('finish-run').hidden=true}
function finish(reached=false){display();stop();finished=true;el('run-status').textContent=reached?'Target distance reached · well done':'Run finished · '+((tracker?.distance||0)/1000).toFixed(2)+' km';el('new-run').hidden=false}
el('finish-run').onclick=()=>finish();el('new-run').onclick=()=>{stop();tracker=null;epoch=0;document.body.classList.remove('running-mode');el('run-live').hidden=true;el('run-setup').hidden=false;demo=false;advice()};
el('demo-run').onclick=async()=>{if(active)return;await prepareAudio();runDistance=km();showLive(true);tracker=StrideRun.createTracker(target);let seconds=target;tracker.update({lat:0,lon:0,accuracy:5,elapsed:0});for(let i=1;i<=101;i++){let r=tracker.update({lat:0,lon:(i*10)/111194.9266,accuracy:5,elapsed:i*seconds/100});r.laps.forEach(lapLine)}el('live-distance').textContent='1.01';el('live-time').textContent=time(seconds*1.01);el('run-status').textContent='DEMO · 1 km completed on target · no GPS used';el('run-status').dataset.state='on';el('new-run').hidden=false};document.addEventListener('visibilitychange',()=>{if(active&&document.visibilityState==='visible'){tracker.resetAnchor();el('run-status').textContent='Back on screen · reacquiring GPS; interrupted splits won’t get a pace alert';if(!paused)keepAwake()}});window.addEventListener('pagehide',stop);advice();})();
